def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
        return f"{local}@{domain}"

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        match = re.search(r"x|ext|#", value, re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        updated = parse_updated(row["updated"])
        email = normalize_email(row.get("email", "") or "")
        if not valid_email(email):
            email = ""
        phone = normalize_phone(row.get("phone", "") or "")

        if not email and not phone:
            continue

        opted_out = (row.get("opted_out", "") or "").strip().lower() in {
            "y", "yes", "true", "1"
        }
        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row.get("tags", "") or "")
            if tag.strip()
        }

        prepared.append({
            "index": index,
            "updated_dt": updated,
            "first_name": normalize_name(row.get("first_name", "") or ""),
            "last_name": normalize_name(row.get("last_name", "") or ""),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "") or ""),
            "source": (row.get("source", "") or "").strip().lower(),
            "opted_out": opted_out,
            "tags": tags,
        })

    # Build connected components so matches are transitive.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def pick(group, field, require_valid=False):
        candidates = [
            row for row in group
            if row[field] and (not require_valid or row[field])
        ]
        if not candidates:
            return ""
        winner = min(
            candidates,
            key=lambda row: (
                row["source"] != "manual",
                -row["updated_dt"].timestamp(),
                row["index"],
            ),
        )
        return winner[field]

    result = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(r["index"] for r in group))

    for group in ordered_groups:
        latest = max(row["updated_dt"] for row in group)
        result.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email", require_valid=True),
            "phone": pick(group, "phone", require_valid=True),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(set().union(*(row["tags"] for row in group)))),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return result
